const flight = $('Elegir vuelo').first().json;
const response = $input.first().json;
const raw =
  response.choices &&
  response.choices[0] &&
  response.choices[0].message
    ? response.choices[0].message.content
    : '{}';

let generated = {};
try {
  let cleaned = String(raw).trim();
  const fence = String.fromCharCode(96).repeat(3);
  cleaned = cleaned.split(fence).join('').trim();
  if (cleaned.toLowerCase().startsWith('json')) {
    cleaned = cleaned.slice(4).trim();
  }
  generated = JSON.parse(cleaned);
} catch (error) {
  generated = {};
}

const title =
  generated.title_overlay ||
  (flight.origin.city + ' - ' + flight.destination.city).toUpperCase();
const subtitle =
  generated.subtitle_overlay ||
  'La ruta entre ' + flight.origin.city + ' y ' + flight.destination.city;
const script = generated.script || '';
const wordCount = script.split(/\s+/).filter(Boolean).length;
const seconds = Math.min(60, Math.max(25, Math.ceil(wordCount / 2.6) + 4));
const totalFrames = Math.ceil(seconds * 30);

return [
  {
    json: {
      type: 'flight',
      compositionId: 'FlightVideo',
      flight_number: flight.flight_number,
      airline: flight.airline,
      origin: flight.origin,
      destination: flight.destination,
      distance_km: flight.distance_km,
      flight_time_formatted: flight.flight_time_formatted,
      title_overlay: title,
      subtitle_overlay: subtitle,
      script,
      totalFrames,
      mapStyle: flight.mapStyle || 'day',
      mapMode: 'auto',
    },
  },
];

const base = $('Preparar render').first().json;
const map = $input.first().json;
return [
  {
    json: {
      ...base,
      mapImageUrl: map.mapImageUrl,
      mapBbox: map.mapBbox,
      mapAttribution: map.mapAttribution,
    },
  },
];
